import {incrementalRecord} from './incremental-registry.js';
import {annualTextHTML} from './annual-localization.js';
import {displayNumber,precisionInputAttributes,readPrecisionInput,bindPrecisionInput} from './number-display.js';
import {UBER_MESSAGES} from './uber-messages.js';
export {UBER_MESSAGES} from './uber-messages.js';
const a=key=>annualTextHTML(UBER_MESSAGES[key][0]),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=value=>displayNumber(value,2),finite=value=>typeof value==='number'&&Number.isFinite(value),object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
export const UBER_POLICY_FIELDS=Object.freeze(['common_shares','existing_earned_award_incremental_shares','existing_option_value_reserve','cash_operating_reserve','investment_asset_value','debt_total_value','finance_lease_claim','nonredeemable_nci_claim','redeemable_nci_claim','legacy_legal_regulatory_tax_claim','income_other_tax_claim','additional_mixed_and_derivative_claim','investment_and_vehicle_commitment_net_cost_reserve','additional_other_claim','included_careem_investment_value']);
const paragraph=(r,key)=>`<p>${annualTextHTML(r.prose[key].en)}</p>`;
export function uberSitePolicyTemplate(record=incrementalRecord('UBER')){return {policy_name:'Edited June conditional allocation',valuation_anchor:'2026-06-30',...Object.fromEntries(UBER_POLICY_FIELDS.map(k=>[k,null]))};}
export function uberSiteRollforwardTemplate(record=incrementalRecord('UBER')){return Object.fromEntries(Object.entries(record.rollforwardTemplate).filter(([key,value])=>key==='as_of'||key==='policy_name'||key==='current_inherited_nondebt_claims'||(value===null&&!key.endsWith('_basis'))).map(([key,value])=>[key,structuredClone(value)]));}
export function uberPolicyEditorHTML(d){
 if(d?.ticker!=='UBER')return '';const r=incrementalRecord('UBER'),p=d.uberPolicy,fields=object(p)?UBER_POLICY_FIELDS.map(k=>`<label>${a(k)}<input type="text" inputmode="decimal" data-precision-grammar="annual" data-uber-policy="${k}" ${precisionInputAttributes(p[k])} aria-describedby="uber-policy-help"></label>`).join(''):'';
 const oct=d.uberRollforward,raw=typeof oct==='string'?oct:JSON.stringify(oct,null,2);
 return `<section class="research-card" id="uber-policy-tool"><h3>${a('title')}</h3><p>${a(p===null?'none':'selected')}</p><div class="result-actions"><button type="button" class="quiet" data-uber-example>${a('example')}</button><button type="button" class="quiet" data-uber-empty>${a('empty')}</button><button type="button" class="quiet" data-uber-clear>${a('clear')}</button></div><div id="uber-policy-help"><p>${a('nulls')}</p>${paragraph(r,'claims')}${paragraph(r,'funding')}</div><div class="research-field-grid">${fields}</div><details><summary>${a('october')}</summary>${paragraph(r,'financing')}${paragraph(r,'wacc')}<p>${a('octoberUnits')}</p><div class="result-actions"><button type="button" class="quiet" data-uber-october-open>${a('openOctober')}</button><button type="button" class="quiet" data-uber-october-clear>${a('clearOctober')}</button></div>${oct===null?`<p>${a('octoberNone')}</p>`:`<label for="uber-october-json">${a('octoberInput')}</label><textarea id="uber-october-json" rows="18" spellcheck="false" aria-describedby="uber-policy-help">${esc(raw)}</textarea>`}</details></section>`;
}
export function bindUberPolicy(root,d,{save,rerender,updateResults,remember,endEdit}={}){
 if(d?.ticker!=='UBER')return;const r=incrementalRecord('UBER');
 const action=(selector,name,fn)=>{const el=root.querySelector(selector);if(el)el.onclick=()=>{remember?.(name);fn();save?.();rerender?.();endEdit?.();root.querySelector(selector)?.focus({preventScroll:true});};};
 action('[data-uber-example]','uber-policy-example',()=>{d.uberPolicy=structuredClone(r.policyExample);});action('[data-uber-empty]','uber-policy-empty',()=>{d.uberPolicy=uberSitePolicyTemplate();});action('[data-uber-clear]','uber-policy-clear',()=>{d.uberPolicy=null;});
 action('[data-uber-october-open]','uber-october-open',()=>{d.uberRollforward=uberSiteRollforwardTemplate();});action('[data-uber-october-clear]','uber-october-clear',()=>{d.uberRollforward=null;});
 root.querySelectorAll('[data-uber-policy]').forEach(el=>{el.onfocus=()=>endEdit?.();el.onblur=()=>endEdit?.();el.oninput=()=>{const key=el.dataset.uberPolicy;if(!UBER_POLICY_FIELDS.includes(key)||!object(d.uberPolicy))return;remember?.('uber:'+key);d.uberPolicy[key]=el.value.trim()===''?null:readPrecisionInput(el);save?.();updateResults?.();};bindPrecisionInput(el);});
 const textarea=root.querySelector('#uber-october-json');if(textarea){textarea.onfocus=()=>endEdit?.();textarea.onblur=()=>endEdit?.();textarea.oninput=()=>{remember?.('uber-october-json');try{d.uberRollforward=JSON.parse(textarea.value);}catch{d.uberRollforward=textarea.value;}save?.();updateResults?.();};}
}
export function uberAllocationHTML(b){
 const r=incrementalRecord('UBER'),oct=b?.uberRollforward;if(!b)return '';
 const october= !oct?a('octoberNone'):oct.status==='suppressed_cash_or_equity_shortfall'?`${a('octoberShortfall')}<br>${a('endingCash')}: ${n(oct.ending_unrestricted_liquidity_assumed)}<br>${a('endingReserve')}: ${n(oct.resolved_assumptions?.current_operating_cash_reserve)}<br>${a('endingEquity')}: ${n(oct.conditional_common_equity_value)}`:finite(oct.conditional_october_allocation_per_share)?`${a('octoberValue')}: ${n(oct.conditional_october_allocation_per_share)}`:a('octoberMissing');
 return `<div class="uber-allocation">${b.uberAllocation?.status==='suppressed_nonpositive_economics'?`<p class="uber-june-shortfall">${a('juneNonpositive')}<br>${a('juneEquity')}: ${n(b.uberAllocation.conditional_common_equity_value)}</p>`:''}${paragraph(r,'claims')}${paragraph(r,'funding')}<p>${a('interimRate')}: ${n(b.interimAccrualRate*100)}%</p><p class="uber-october-allocation">${october}</p>${paragraph(r,'financing')}</div>`;
}
export function uberCalculationHTML(op){const rows=op?.uberCalculation?.annual_forecast;if(!rows)return '';const labels=['fiscalYear','booking','grossAsset','da','nwc','insurance','collateral'];return `<div class="research-table-scroll"><table class="research-table"><caption>${a('calculation')}</caption><thead><tr>${labels.map(k=>`<th scope="col">${a(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${esc(row.period_end)}</th>${['gross_bookings','gross_operating_asset_reinvestment','operating_da_addback','delta_noninsurance_nwc','delta_insurance_reserve','delta_restricted_pool'].map(k=>`<td>${n(row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export function uberHistoryHTML(d,key='growth'){
 if(d?.ticker!=='UBER'||!['growth','profitability','capital','history'].includes(key))return '';const r=incrementalRecord('UBER'),cols=key==='growth'?[['revenue','revenue']]:key==='profitability'?[['ebit','gaap_operating_income']]:[['cfo','cfo'],['capex','cash_ppe_capex'],['da','income_statement_da']];
 return `<section class="research-card uber-history-reference" data-uber-history="${key}"><h4>${a('historyTitle')}</h4>${paragraph(r,'history')}${key==='growth'?paragraph(r,'growth'):key==='capital'?paragraph(r,'capital'):paragraph(r,'profitability')}<div class="research-table-scroll" tabindex="0"><table class="research-table"><caption>${a('historyTitle')} · USDm</caption><thead><tr><th scope="col">${a('fiscalYear')}</th>${cols.map(([label])=>`<th scope="col">${a(label)}</th>`).join('')}</tr></thead><tbody>${r.history.map(row=>`<tr><th scope="row">${esc(row.fiscalYear)}${row.fiscalYear===2016?`<br>${a('history2016')}`:row.fiscalYear===2017?`<br>${a('historyRecast')}`:''}</th>${cols.map(([,field])=>`<td>${finite(row[field])?n(row[field]):a('missing')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><a href="${esc(r.identity.provenancePath)}" target="_blank" rel="noopener">${a('source')}</a></p></section>`;
}
